INSERT INTO settlements (
    appointment_id, created_by_member_id, payer_member_id, source_transfer_id,
    idempotency_key, request_fingerprint, settlement_status, split_method,
    total_amount, payer_share_amount, receivable_amount, memo
) VALUES (
    #{appointmentId}, #{createdByMemberId}, #{payerMemberId}, #{sourceTransferId},
    #{idempotencyKey}, #{requestFingerprint}, #{settlementStatus}, #{splitMethod},
    #{totalAmount}, #{payerShareAmount}, #{receivableAmount}, #{memo}
)

INSERT INTO settlement_item_shares (
    settlement_item_id, settlement_member_id, allocated_quantity, allocated_amount
) VALUES

    (
        #{share.settlementItemId},
        (
            SELECT settlement_member_id
            FROM settlement_members
            WHERE settlement_id = #{settlementId}
              AND appointment_member_id = #{share.appointmentMemberId}
              AND deleted_at IS NULL
        ),
        #{share.allocatedQuantity}, #{share.allocatedAmount}
    )
